def translate_dictionary_values(dictionary, config=None):
    config = config or {}
    translated_dictionary = {}
    for key, value in dictionary.items():
        translated_value = translate_text({'text': value, 'source_language': 'en', 'target_language': 'es'}, config)
        translated_dictionary[key] = translated_value['text']
    return translated_dictionary

import os


def get_translation_config():
    return {
        'api_key': os.getenv('MICROSOFT_TRANSLATOR_API_KEY'),
        'region': os.getenv('MICROSOFT_TRANSLATOR_REGION')
    }


def get_translation_client():
    config = get_translation_config()
    return {
        'api_key': config['api_key'],
        'region': config['region']
    }

def normalize_translation_payload(payload):
    return {
        'text': payload['text'],
        'source_language': payload['source_language'],
        'target_language': payload['target_language']
    }


def normalize_translation_response(response):
    return {
        'text': response['text'],
        'source_language': response['source_language'],
        'target_language': response['target_language']
    }
